import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.BQGW-Zpy.js";const m=JSON.parse('{"title":"Why This Is Legal","description":"","frontmatter":{},"headers":[],"relativePath":"legal/why-this-is-legal.md","filePath":"legal/why-this-is-legal.md"}'),i={name:"legal/why-this-is-legal.md"};function n(s,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="why-this-is-legal" tabindex="-1">Why This Is Legal <a class="header-anchor" href="#why-this-is-legal" aria-label="Permalink to &quot;Why This Is Legal&quot;">​</a></h1><h2 id="the-core-constraint" tabindex="-1">The core constraint <a class="header-anchor" href="#the-core-constraint" aria-label="Permalink to &quot;The core constraint&quot;">​</a></h2><p><strong>We never hold funds or crypto-assets, at any point.</strong> Every architectural decision in this project exists to hold that line.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>Under PSD2, providing a payment service on behalf of clients requires authorisation as a Payment Institution or EMI. The EBA has confirmed that transferring EMTs on behalf of clients is a payment service, and that a custodial wallet is a payment account.</p><p>We do neither:</p><ul><li>We never receive the sender&#39;s funds, the <strong>licensed PSP</strong> does.</li><li>We never hold the stablecoin on a client&#39;s behalf, the <strong>licensed parties</strong> hold their own.</li><li>We never operate a wallet in a client&#39;s name.</li></ul><p>This is the EBA&#39;s <strong>scenario 2</strong>, partnering with an authorised PSP — explicitly contemplated in the regulatory guidance issued when the dual-licensing regime took effect.</p><h2 id="what-we-actually-do" tabindex="-1">What we actually do <a class="header-anchor" href="#what-we-actually-do" aria-label="Permalink to &quot;What we actually do&quot;">​</a></h2><p>We <strong>orchestrate</strong> (route a transfer through the right sequence of licensed parties) and <strong>anchor</strong> (make each compliance/routing decision independently verifiable). Neither activity requires holding an asset.</p><h2 id="the-moment-the-model-would-break" tabindex="-1">The moment the model would break <a class="header-anchor" href="#the-moment-the-model-would-break" aria-label="Permalink to &quot;The moment the model would break&quot;">​</a></h2><p>If this system ever received a crypto-asset or fiat balance on a client&#39;s behalf, even briefly, even for &quot;just settlement&quot;, it would become a custodian, requiring its own CASP and PI/EMI authorisation. <code>execute.mjs</code>&#39;s clearly-labeled non-execution for chains without a licensed-partner integration exists specifically to avoid this: we do not quietly become a custodian just to make a demo look complete.</p><h2 id="a-related-question-kyc-doesn-t-transfer" tabindex="-1">A related question: KYC doesn&#39;t transfer <a class="header-anchor" href="#a-related-question-kyc-doesn-t-transfer" aria-label="Permalink to &quot;A related question: KYC doesn&#39;t transfer&quot;">​</a></h2><p>A tempting (and wrong) shortcut: &quot;the bank already did KYC, so we inherit it.&quot; The bank verified <strong>its own customer</strong> for <strong>its own relationship</strong>, that verification does not transfer to a third party moving value on that customer&#39;s behalf. Each regulated party carries its own due-diligence obligation. What we do instead: record that a check was performed, by whom, and when, as a verifiable hash, see <a href="./../architecture/trust-layer.html">The Trust Layer</a>.</p>',14)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
